<?php require_once __DIR__.'/../../config/seguranca.php';exigirAdmin();$pageTitle='Cliente';require __DIR__.'/../_header.php';$pdo=getPDO();$id=(int)($_GET['id']??0);$user=null;$orders=[];if($pdo){$st=$pdo->prepare('SELECT id,nome,email,telefone,criado_em FROM usuarios WHERE id=?');$st->execute([$id]);$user=$st->fetch();if($user){$st=$pdo->prepare('SELECT id,total,status,criado_em FROM pedidos WHERE usuario_id=? ORDER BY id DESC LIMIT 10');$st->execute([$id]);$orders=$st->fetchAll();}}?><div class="admin-heading"><div><h1>Cliente</h1></div><a class="admin-btn secondary" href="<?=url('admin/clientes/index.php')?>">← Clientes</a></div><?php if(!$user):?><div class="admin-card"><div class="empty-state">Cliente não encontrado.</div></div><?php else:?><div class="dashboard-grid"><section class="admin-card"><h2>Dados</h2><p style="font-size:.72rem;line-height:1.9"><strong><?=e($user['nome'])?></strong><br><?=e($user['email'])?><br><?=e($user['telefone'])?><br>Cadastro: <?=formatarData($user['criado_em'])?></p></section><section class="admin-card"><h2>Pedidos recentes</h2><?php if(!$orders):?><p style="font-size:.7rem;color:var(--muted)">Nenhum pedido.</p><?php else:?><div class="table-wrap"><table class="data-table"><tbody><?php foreach($orders as $o):?><tr><td>#<?=e($o['id'])?></td><td><?=formatarMoeda((float)$o['total'])?></td><td><span class="status-pill <?=statusClasse($o['status'])?>"><?=e(statusLabel($o['status']))?></span></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div><?php endif;?><?php require __DIR__.'/../_footer.php'; ?>
